func:
const tLlegada = Date.now();
const cfg = global.get('config');
if (!cfg) { node.error('Parametros no cargados', msg); return null; }

const c = flow.get('contadores') || { recibidos: 0, validos: 0, invalidos: 0, duplicados: 0, perdidos: 0 };
c.recibidos++;

const crudo = String(msg.payload).substring(0, 160);
const esNum = (v) => typeof v === 'number' && Number.isFinite(v);

let d = null;
try { d = JSON.parse(msg.payload); } catch (e) { d = null; }

const errores = [];
let dispositivo = 'desconocido';

if (d === null || typeof d !== 'object' || Array.isArray(d)) {
  errores.push('json_invalido');
} else {
  if (typeof d.dispositivo === 'string' && d.dispositivo.length > 0) dispositivo = d.dispositivo;
  else errores.push('dispositivo_faltante');

  if (!esNum(d.temperatura)) errores.push('temperatura_no_numerica');
  else if (d.temperatura < cfg.temp_min_valida || d.temperatura > cfg.temp_max_valida) errores.push('temperatura_fuera_de_rango');

  if (!esNum(d.humedad)) errores.push('humedad_no_numerica');
  else if (d.humedad < cfg.hum_min_valida || d.humedad > cfg.hum_max_valida) errores.push('humedad_fuera_de_rango');

  if (!esNum(d.ldr_raw)) errores.push('ldr_no_numerico');
  else if (d.ldr_raw < 0 || d.ldr_raw > cfg.ldr_max) errores.push('ldr_fuera_de_rango');

  if (!esNum(d.luz_porcentaje)) errores.push('luz_no_numerica');
  else if (d.luz_porcentaje < 0 || d.luz_porcentaje > 100) errores.push('luz_fuera_de_rango');

  if (!esNum(d.seq) || d.seq < 0) errores.push('seq_invalido');
}

if (errores.length > 0) {
  c.invalidos++;
  flow.set('contadores', c);
  node.status({ fill: 'red', shape: 'dot', text: 'invalido: ' + errores[0] + ' (' + c.invalidos + ')' });
  msg.invalido = { dispositivo: dispositivo, motivo: errores.join(','), crudo: crudo };
  return [null, msg];
}

c.validos++;
flow.set('contadores', c);
flow.set('ultimo_dispositivo', dispositivo);

let tsDisp = null, latencia = null;
if (esNum(d.ts_ms) && d.ts_ms > 1700000000000) {
  tsDisp = d.ts_ms;
  const lat = tLlegada - d.ts_ms;
  if (lat >= -5000 && lat <= 30000) latencia = lat;   // fuera de este rango se considera reloj no confiable
}

node.status({ fill: 'green', shape: 'dot', text: 'ok ' + c.validos + ' | inv ' + c.invalidos + (latencia !== null ? ' | lat ' + Math.round(latencia) + ' ms' : '') });

msg.lectura = {
  dispositivo: dispositivo,
  seq: d.seq,
  temperatura: d.temperatura,
  humedad: d.humedad,
  ldr_raw: d.ldr_raw,
  luz_porcentaje: d.luz_porcentaje,
  ts_ms: tsDisp,
  latencia_ms: latencia
};
return [msg, null];

const l = msg.lectura
const c = flow.get('contadores') || { recibidos: 0, validos: 0, invalidos: 0, duplicados: 0, perdidos: 0 };
const mapa = flow.get('seq_dispositivos') || {};
const prev = mapa[l.dispositivo];

const calidad = { perdidos: 0, tipo: null, seq_anterior: (prev === undefined ? -1 : prev) };

if (prev !== undefined) {
  if (l.seq === prev) {
    c.duplicados = (c.duplicados || 0) + 1;
    flow.set('contadores', c);
    node.status({ fill: 'yellow', shape: 'ring', text: 'duplicado seq ' + l.seq + ' descartado' });
    return null;
  } else if (l.seq > prev + 1) {
    calidad.perdidos = l.seq - prev - 1;
    calidad.tipo = 'mensajes_perdidos';
    c.perdidos = (c.perdidos || 0) + calidad.perdidos;
  } else if (l.seq < prev) {
    calidad.tipo = 'reinicio_dispositivo';
  }
}

mapa[l.dispositivo] = l.seq;
flow.set('seq_dispositivos', mapa);
flow.set('contadores', c);

node.status({
  fill: calidad.perdidos > 0 ? 'yellow' : 'green',
  shape: 'dot',
  text: 'seq ' + l.seq + ' | perdidos acum. ' + (c.perdidos || 0)
});

msg.calidad = calidad;
return msg;

const cfg = global.get('config');
if (!cfg) { node.error('Parametros no cargados', msg); return null; }

const l = msg.lectura;
const q = msg.calidad;
const ahora = new Date();
const horaLima = (ahora.getUTCHours() - 5 + 24) % 24;   // Lima = UTC-5 (sin horario de verano)


let estadoTemp = 'normal', codTemp = 0;
if (l.temperatura >= cfg.umbral_critico) { estadoTemp = 'critico'; codTemp = 2; }
else if (l.temperatura >= cfg.umbral_advertencia) { estadoTemp = 'advertencia'; codTemp = 1; }

let estadoLuz = 'iluminado', codLuz = 2;
if (l.luz_porcentaje <= cfg.luz_oscuro_max) { estadoLuz = 'oscuro'; codLuz = 0; }
else if (l.luz_porcentaje <= cfg.luz_tenue_max) { estadoLuz = 'tenue'; codLuz = 1; }

const fueraVentana = !(horaLima >= cfg.ventana_inicio_h && horaLima < cfg.ventana_fin_h);

const estados = flow.get('estados') || {};
const prev = estados[l.dispositivo] || { temp: 'desconocido', luz_fuera: false, ultimo_recordatorio: 0 };

const eventos = [];
const nuevoEvento = (tipo, severidad, mensaje, extra) => eventos.push(Object.assign({
  ts: ahora.toISOString(),
  dispositivo: l.dispositivo,
  tipo: tipo,
  severidad: severidad,
  mensaje: mensaje,
  temperatura: l.temperatura,
  luz_porcentaje: l.luz_porcentaje
}, extra || {}));

const t = l.temperatura.toFixed(1);
if (estadoTemp !== prev.temp) {
  if (estadoTemp === 'critico') {
    const td = (l.ts_ms !== null) ? (Date.now() - l.ts_ms) : null;
    const extra = (td !== null && td >= -5000 && td <= 30000) ? { tiempo_deteccion_ms: td } : {};
    nuevoEvento('temperatura_critica', 'critica', 'Temperatura crítica: ' + t + ' C (umbral crítico: ' + cfg.umbral_critico + ' C)', extra);
    prev.ultimo_recordatorio = ahora.getTime();
  } else if (estadoTemp === 'advertencia') {
    nuevoEvento('temperatura_advertencia', 'advertencia', 'Temperatura en advertencia: ' + t + ' C (umbral: ' + cfg.umbral_advertencia + ' C)');
  } else if (prev.temp === 'advertencia' || prev.temp === 'critico') {
    nuevoEvento('temperatura_normalizada', 'info', 'Temperatura normalizada: ' + t + ' C');
  }
} else if (estadoTemp === 'critico' && (ahora.getTime() - prev.ultimo_recordatorio) >= cfg.recordatorio_critico_s * 1000) {
  nuevoEvento('temperatura_critica_persistente', 'critica', 'La condición crítica persiste: ' + t + ' C');
  prev.ultimo_recordatorio = ahora.getTime();
}
prev.temp = estadoTemp;

const luzFuera = (estadoLuz === 'iluminado' && fueraVentana);
if (luzFuera && !prev.luz_fuera) {
  nuevoEvento('iluminacion_fuera_de_ventana', 'info',
    'Iluminación alta (' + l.luz_porcentaje + ' %) fuera de la ventana de mantenimiento (' +
    cfg.ventana_inicio_h + ':00-' + cfg.ventana_fin_h + ':00). Es una variable ambiental: no indica presencia de personas.');
}
prev.luz_fuera = luzFuera;

estados[l.dispositivo] = prev;
flow.set('estados', estados);

const puntos = [];

const monitoreoPrev = flow.get('monitoreo');
if (monitoreoPrev !== 'EN_LINEA') {
  puntos.push({
    measurement: 'estado_monitoreo',
    tags: { dispositivo: l.dispositivo, fuente: 'node-red' },
    fields: { estado_codigo: 2, estado_texto: 'EN_LINEA' },
    timestamp: ahora
  });
  if (monitoreoPrev === 'SIN_DATOS' || monitoreoPrev === 'DESCONECTADO') {
    nuevoEvento('datos_recuperados', 'info', 'Se reanudó la recepción de lecturas (estado previo: ' + monitoreoPrev + ')');
  }
  flow.set('monitoreo', 'EN_LINEA');
}

const camposLectura = {
    temperatura: l.temperatura,
    humedad: l.humedad,
    ldr_raw: l.ldr_raw,
    luz_porcentaje: l.luz_porcentaje,
    seq: l.seq,
    perdidos: q.perdidos,
    estado_temp: estadoTemp,
    estado_temp_codigo: codTemp,
    estado_luz: estadoLuz,
    estado_luz_codigo: codLuz
};
if (l.latencia_ms !== null) camposLectura.latencia_ms = l.latencia_ms;
if (l.ts_ms !== null) camposLectura.ts_dispositivo_ms = l.ts_ms;
puntos.push({
  measurement: 'lecturas_sala',
  tags: { dispositivo: l.dispositivo, sala: cfg.sala },
  fields: camposLectura,
  timestamp: ahora
});

if (q.tipo) {
  puntos.push({
    measurement: 'calidad_datos',
    tags: { dispositivo: l.dispositivo, tipo: q.tipo },
    fields: { perdidos: q.perdidos, seq: l.seq, seq_anterior: q.seq_anterior },
    timestamp: ahora
  });
}

for (const e of eventos) {
  const campos = { mensaje: e.mensaje, temperatura: e.temperatura, luz_porcentaje: e.luz_porcentaje };
  if (e.tiempo_deteccion_ms !== undefined) campos.tiempo_deteccion_ms = e.tiempo_deteccion_ms;
  puntos.push({
    measurement: 'alertas',
    tags: { dispositivo: e.dispositivo, tipo: e.tipo, severidad: e.severidad },
    fields: campos,
    timestamp: ahora
  });
}

node.status({
  fill: codTemp === 2 ? 'red' : (codTemp === 1 ? 'yellow' : 'green'),
  shape: 'dot',
  text: t + ' C ' + estadoTemp + ' | luz ' + estadoLuz
});

msg.payload = puntos;
const msgsEventos = eventos.map((e) => ({ payload: e }));
return [msg, msgsEventos.length > 0 ? msgsEventos : null];

const i = msg.invalido;
msg.payload = [{
  measurement: 'lecturas_invalidas',
  tags: { dispositivo: i.dispositivo, motivo: i.motivo.split(',')[0] },
  fields: { detalle: i.motivo, crudo: i.crudo },
  timestamp: new Date()
}];
return msg;

const monitoreo = flow.get('monitoreo');
if (monitoreo === 'DESCONECTADO' || monitoreo === 'SIN_DATOS') return null;

const dispositivo = flow.get('ultimo_dispositivo') || 'esp32-sala01';
const ahora = new Date();
flow.set('monitoreo', 'SIN_DATOS');

const e = {
  ts: ahora.toISOString(),
  dispositivo: dispositivo,
  tipo: 'sin_datos',
  severidad: 'advertencia',
  mensaje: 'No se reciben lecturas desde hace más de 10 s (posible interrupción de la publicación o pérdida de mensajes)'
};

msg.payload = [
  {
    measurement: 'estado_monitoreo',
    tags: { dispositivo: dispositivo, fuente: 'watchdog' },
    fields: { estado_codigo: 1, estado_texto: 'SIN_DATOS' },
    timestamp: ahora
  },
  {
    measurement: 'alertas',
    tags: { dispositivo: dispositivo, tipo: e.tipo, severidad: e.severidad },
    fields: { mensaje: e.mensaje },
    timestamp: ahora
  }
];

node.status({ fill: 'yellow', shape: 'ring', text: 'SIN_DATOS' });
return [msg, { payload: e }];

const estado = String(msg.payload).trim().toLowerCase();
const dispositivo = flow.get('ultimo_dispositivo') || 'esp32-sala01';
const ahora = new Date();

if (estado === 'offline') {
  if (flow.get('monitoreo') === 'DESCONECTADO') return null;
  flow.set('monitoreo', 'DESCONECTADO');
  const e = {
    ts: ahora.toISOString(), dispositivo: dispositivo, tipo: 'dispositivo_offline', severidad: 'advertencia',
    mensaje: 'El broker publicó el Last Will: el ESP32 se desconectó.'
  };
  msg.payload = [
    {
      measurement: 'estado_monitoreo',
      tags: { dispositivo: dispositivo, fuente: 'lwt' },
      fields: { estado_codigo: 0, estado_texto: 'DESCONECTADO' },
      timestamp: ahora
    },
    {
      measurement: 'alertas',
      tags: { dispositivo: dispositivo, tipo: e.tipo, severidad: e.severidad },
      fields: { mensaje: e.mensaje },
      timestamp: ahora
    }
  ];
  node.status({ fill: 'red', shape: 'dot', text: 'ESP32 offline' });
  return [msg, { payload: e }];
}

if (estado === 'online') {
  const e = {
    ts: ahora.toISOString(), dispositivo: dispositivo, tipo: 'dispositivo_online', severidad: 'info',
    mensaje: 'El ESP32 se conectó al broker MQTT.'
  };
  msg.payload = [{
    measurement: 'alertas',
    tags: { dispositivo: dispositivo, tipo: e.tipo, severidad: e.severidad },
    fields: { mensaje: e.mensaje },
    timestamp: ahora
  }];
  node.status({ fill: 'green', shape: 'dot', text: 'ESP32 online' });
  return [msg, { payload: e }];
}

node.warn('Estado desconocido en el topico estado: ' + estado);
return null;

let d;
try { d = JSON.parse(msg.payload); } catch (e) { d = { error: 'payload_no_json' }; }
if (d === null || typeof d !== 'object') d = { error: 'payload_no_json' };

const dispositivo = (typeof d.dispositivo === 'string' && d.dispositivo) ? d.dispositivo : 'desconocido';
const codigo = (typeof d.error === 'string' && d.error) ? d.error : 'error_desconocido';
const ahora = new Date();

const puntos = [];
puntos.push({
  measurement: 'lecturas_invalidas',
  tags: { dispositivo: dispositivo, motivo: codigo },
  fields: { detalle: 'reportado_por_dispositivo', crudo: String(msg.payload).substring(0, 160) },
  timestamp: ahora
});

const ult = flow.get('ult_alerta_error') || 0;
let salidaEvento = null;
if (ahora.getTime() - ult >= 30000) {
  flow.set('ult_alerta_error', ahora.getTime());
  const e = {
    ts: ahora.toISOString(), dispositivo: dispositivo, tipo: 'error_sensor', severidad: 'advertencia',
    mensaje: 'El ESP32 reportó una lectura inválida del sensor (' + codigo + ').'
  };
  puntos.push({
    measurement: 'alertas',
    tags: { dispositivo: dispositivo, tipo: e.tipo, severidad: e.severidad },
    fields: { mensaje: e.mensaje },
    timestamp: ahora
  });
  salidaEvento = { payload: e };
}

node.status({ fill: 'yellow', shape: 'dot', text: 'error sensor: ' + codigo });
msg.payload = puntos;
return [msg, salidaEvento];

const ahora = Date.now();
const ult = flow.get('ult_error_influx') || 0;
if (ahora - ult < 30000) return null;
flow.set('ult_error_influx', ahora);

const detalle = (msg.error && msg.error.message) ? msg.error.message : 'error desconocido';
const http = (msg.influx_error && msg.influx_error.statusCode) ? ' (HTTP ' + msg.influx_error.statusCode + ')' : '';

return {
  payload: {
    ts: new Date().toISOString(),
    dispositivo: 'node-red',
    tipo: 'error_escritura_influxdb',
    severidad: 'critica',
    mensaje: 'Fallo al escribir en InfluxDB' + http + ': ' + detalle
  }
};

const e = msg.payload;
const ts = new Date(e.ts || Date.now()).toLocaleString('sv-SE', { timeZone: 'America/Lima' });
const linea = ts + ' [' + String(e.severidad).toUpperCase() + '] ' + e.tipo +
              ' | dispositivo=' + e.dispositivo + ' | ' + e.mensaje +
              (e.tiempo_deteccion_ms !== undefined ? ' | deteccion=' + Math.round(e.tiempo_deteccion_ms) + ' ms' : '');

node.status({
  fill: e.severidad === 'critica' ? 'red' : (e.severidad === 'advertencia' ? 'yellow' : 'blue'),
  shape: 'dot',
  text: e.tipo
});

return [{ payload: e }, { payload: linea }];
